#define _POSIX_C_SOURCE 200809L
#include "coh_power_stream.h"
#include <openssl/sha.h>
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
typedef struct {int fd;uint32_t base;SHA256_CTX sha;uint32_t next,reads,updates,begins,finishes,aborts,fail_read,fail_update,cancel_at,mutate_at,polls,cancel_poll;unsigned fail_begin,fail_finish,wrong_digest;} Context;
static unsigned long checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"FAIL line %u: %s\n",__LINE__,#x);abort();}}while(0)
static CohStatus rd(void*p,uint32_t offset,uint8_t*out,size_t n){Context*c=p;c->reads++;CHECK(n<=4096&&offset==c->next);if(c->fail_read&&c->reads==c->fail_read)return COH_IO;ssize_t got=pread(c->fd,out,n,c->base+offset);if(got!=(ssize_t)n)return COH_IO;if(c->mutate_at>=offset&&c->mutate_at-offset<n)out[c->mutate_at-offset]^=1;c->next+=(uint32_t)n;return COH_OK;}
static CohStatus begin(void*p){Context*c=p;c->begins++;c->next=c->reads=c->updates=0;if(c->fail_begin)return COH_IO;CHECK(SHA256_Init(&c->sha));return COH_OK;}
static CohStatus update(void*p,CohBytes b){Context*c=p;c->updates++;if(c->fail_update&&c->updates==c->fail_update)return COH_IO;CHECK(SHA256_Update(&c->sha,b.data,b.size));return COH_OK;}
static CohStatus finish(void*p,uint8_t out[32]){Context*c=p;c->finishes++;if(c->fail_finish)return COH_IO;CHECK(SHA256_Final(out,&c->sha));if(c->wrong_digest)out[0]^=1;return COH_OK;}
static void stop(void*p){Context*c=p;c->aborts++;memset(&c->sha,0,sizeof(c->sha));}
static int cancel(void*p){Context*c=p;c->polls++;return (c->cancel_at&&c->reads>=c->cancel_at)||(c->cancel_poll&&c->polls>=c->cancel_poll);}
static void clean(Context*c){int fd=c->fd;memset(c,0,sizeof(*c));c->fd=fd;c->mutate_at=UINT32_MAX;}
int main(int argc,char**argv){
 CHECK(argc==4);Context c={0};c.fd=open(argv[1],O_RDONLY);CHECK(c.fd>=0);int original_fd=c.fd;clean(&c);CohPowerStreamProvider p={&c,sizeof(c),16384,62047164,1,rd,begin,update,finish,stop,cancel};
 const uint8_t digest[32]={0x25,0x64,0x1e,0x74,0x7c,0x60,0xe0,0x66,0x01,0x6f,0xcc,0x7d,0x2c,0xe0,0xa2,0xe7,0x2f,0x57,0xd7,0xd3,0x95,0x3f,0x7b,0x1f,0xf4,0xb1,0x8b,0x69,0xe2,0xd4,0x9c,0x6d};
 CohPowerStreamDictionary*out=malloc(sizeof(*out)),*saved=malloc(sizeof(*saved));CohPowerStreamWorkspace*w=malloc(sizeof(*w));CHECK(out&&saved&&w);memset(out,0xa5,sizeof(*out));
 CohStatus status=coh_power_stream_read(&p,digest,out,w,COH_POWER_STREAM_RAM_MAX,0);fprintf(stderr,"baseline status=%u owner=%zu workspace=%zu reads=%u\n",status,sizeof(*out),sizeof(*w),c.reads);CHECK(status==COH_OK);CHECK(c.begins==1&&c.finishes==1&&!c.aborts&&c.next==p.input_bytes);CHECK(out->count==20241&&out->unique_count==20241&&!out->duplicate_count);CHECK(out->table_counts[0]==20241&&out->table_counts[1]==113046&&out->table_counts[2]==7165&&out->table_counts[3]==0&&out->table_counts[4]==7103);CHECK(out->observed_schema_crc==0xb553b8ff&&!out->source_crc_recomputed&&!out->runtime_generation&&!out->actor_authority);CHECK(out->index_slots==32768);memcpy(saved,out,sizeof(*out));
 FILE*f=fopen(argv[2],"rb");CHECK(f);for(unsigned i=0;i<out->count;i++){CohPowerStreamEntry expected;CHECK(fread(&expected,sizeof(expected),1,f)==1);CHECK(!memcmp(&expected,&out->entries[i],sizeof(expected)));uint32_t row=UINT32_MAX;CHECK(coh_power_stream_find_crc(out,out->entries[i].crc,&row)==COH_OK&&row==i);}for(unsigned k=0;k<65536;k++){uint32_t expected;CHECK(fread(&expected,4,1,f)==1);CHECK(out->slots[k]==expected);}CHECK(fgetc(f)==EOF);fclose(f);
 size_t exact=COH_POWER_STREAM_STACK_RESERVE+sizeof(p)+32+sizeof(*out)+sizeof(*w)+sizeof(c)+p.scratch_reserve;
 clean(&c);CHECK(coh_power_stream_read(&p,digest,out,w,exact-1,0)==COH_LIMIT&&!c.begins);CHECK(!memcmp(saved,out,sizeof(*out)));
 for(unsigned mode=0;mode<10;mode++){clean(&c);switch(mode){case 0:c.fail_begin=1;break;case 1:c.fail_read=1;break;case 2:c.fail_read=15000;break;case 3:c.fail_update=1;break;case 4:c.fail_update=15000;break;case 5:c.cancel_at=15000;break;case 6:c.fail_finish=1;break;case 7:c.wrong_digest=1;break;case 8:c.mutate_at=62047160;break;case 9:c.mutate_at=668400;break;}status=coh_power_stream_read(&p,digest,out,w,exact,0);CHECK(status!=COH_OK);CHECK(!memcmp(saved,out,sizeof(*out)));CHECK(c.begins==1);CHECK((c.finishes&&!c.fail_finish)?!c.aborts:c.aborts==1);}
 clean(&c);CHECK(coh_power_stream_read(&p,digest,out,w,exact,1)==COH_LIMIT&&!c.begins);CHECK(coh_power_stream_read(&p,digest,(CohPowerStreamDictionary*)w,w,exact,0)==COH_INVALID&&!c.begins);CHECK(coh_power_stream_read(&p,digest,out,w,exact,0)==COH_OK);CHECK(!memcmp(saved,out,sizeof(*out)));
 uint32_t row=123;CHECK(coh_power_stream_find_crc(out,0,&row)==COH_INVALID&&row==123);CHECK(coh_power_stream_find_crc(out,1,&row)==COH_NOT_FOUND&&row==123);CHECK(coh_power_stream_find_crc(out,1,(uint32_t*)out)==COH_INVALID);
 FILE*variants=fopen(argv[3],"rb");CHECK(variants);uint32_t cases;CHECK(fread(&cases,4,1,variants)==1&&cases==6);for(unsigned scenario=0;scenario<cases;scenario++){uint32_t bytes;uint8_t hash[32];CHECK(fread(&bytes,4,1,variants)==1);CHECK(fread(hash,32,1,variants)==1);clean(&c);c.fd=fileno(variants);c.base=(uint32_t)ftello(variants);p.input_bytes=bytes;memcpy(out,saved,sizeof(*out));status=coh_power_stream_read(&p,hash,out,w,exact,0);if(scenario==3){CHECK(status==COH_STATE&&!memcmp(out,saved,sizeof(*out))&&c.aborts==1);}else{CHECK(status==COH_OK&&out->count==(scenario==5?2u:1u)&&out->unique_count==1&&out->duplicate_count==(scenario==5));CHECK(out->table_counts[3]==(scenario==2));CHECK(out->raw_schema_validated&&!out->runtime_generation&&!out->actor_authority);uint32_t first_index=123;CHECK(coh_power_stream_find_crc(out,out->entries[0].crc,&first_index)==COH_OK&&first_index==0);}if(scenario==0){unsigned final_poll=c.polls;memcpy(saved,out,sizeof(*out));uint32_t original_bytes=p.input_bytes;for(uint32_t cut=1;cut<bytes;cut+=17){clean(&c);c.fd=fileno(variants);c.base=(uint32_t)ftello(variants);p.input_bytes=cut;CHECK(coh_power_stream_read(&p,hash,out,w,exact,0)!=COH_OK);CHECK(!memcmp(saved,out,sizeof(*out))&&c.aborts==1);}p.input_bytes=original_bytes;for(uint32_t offset=0;offset<bytes;offset+=31){clean(&c);c.fd=fileno(variants);c.base=(uint32_t)ftello(variants);c.mutate_at=offset;CHECK(coh_power_stream_read(&p,hash,out,w,exact,0)!=COH_OK);CHECK(!memcmp(saved,out,sizeof(*out)));}p.input_bytes=original_bytes;for(unsigned late=0;late<3;late++){clean(&c);c.fd=fileno(variants);c.base=(uint32_t)ftello(variants);if(!late)c.cancel_at=(bytes+4095)/4096;else c.cancel_poll=final_poll-(late==2);CHECK(coh_power_stream_read(&p,hash,out,w,exact,0)==COH_CANCELLED);CHECK(!memcmp(saved,out,sizeof(*out)));CHECK(late==1?(c.finishes==1&&!c.aborts):(!c.finishes&&c.aborts==1));}}CHECK(fseeko(variants,bytes,SEEK_CUR)==0);}CHECK(fgetc(variants)==EOF);fclose(variants);
 printf("{\"checks\":%lu,\"owner_bytes\":%zu,\"workspace_bytes\":%zu,\"provider_bytes\":%zu,\"exact_aggregate\":%zu,\"raw_schema_crc\":3042162943,\"count\":20241,\"runtime_generation\":false,\"actor_authority\":false}\n",checks,sizeof(*out),sizeof(*w),sizeof(c),exact);free(out);free(saved);free(w);close(original_fd);return 0;
}
